insert into public.concepts
  (id, term, aliases, said, alias_list, status, one_liner, analogy, example, related, deeper, lens_pm, lens_eng, domain, priority, tags)
values
  ('openrouter', 'OpenRouter', '', 'OpenRouter', ARRAY['open router']::text[], 'Rising', 'A unified API gateway that routes requests to multiple model providers—pick your model, pick your price point.', 'A travel agent who books flights on whichever airline is cheapest that day, same destination either way.', 'A startup building with GPT-4 on Monday realizes it''s expensive, switches to Claude 3 on Tuesday, then to Llama on Wednesday—all without changing a line of code.', '[]'::jsonb, 'OpenRouter abstracts provider differences, caches keys, rate-limits across models, and lets you compare pricing and latency in real time. You''re vendor-flexible, but you still own your usage data and API keys stay client-side. Catch: some models cost more through routers than directly.', 'Reduces switching costs and lets you negotiate better pricing by playing providers against each other.', 'Simplifies multi-model fallback logic and A/B testing between providers at runtime.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('cursor', 'Cursor', '', 'Cursor', ARRAY['cursor editor','cursor IDE']::text[], 'Rising', 'A coding IDE that''s Claude + TypeScript + file context baked into your editor.', 'A pair programmer who remembers all your files and can edit them directly, right there in your workspace.', 'You ask Cursor to refactor a 200-line component. It reads the full file, your dependencies, and related tests in one shot, then edits all of it inline.', '[]'::jsonb, 'Cursor embeds Claude directly into VS Code–like UX, gives Claude read access to your whole codebase, and lets Claude make file edits with your approval. The local context window means fast iteration. Privacy tradeoff: your code goes to Anthropic''s servers.', 'Shortens engineer task time on routine coding work and reduces back-and-forth.', 'LLM has full file and repo context, enabling multi-file edits and understanding of your actual dependencies.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('githubcopilot', 'GitHub Copilot', '', 'GitHub Copilot', ARRAY['GitHub Copilot X']::text[], 'Core', 'Code completion and generation powered by a GPT model, trained on open-source code, baked into your editor.', 'An autocomplete that learned from millions of GitHub repos, so it knows not just English but *code patterns*.', 'You start typing a function to validate an email address, and Copilot suggests a whole regex pattern and error handling—you accept or skip.', '[]'::jsonb, 'Copilot is a fine-tuned code model (originally GPT-3 based, now includes GPT-4). It runs on GitHub''s side and streams completions to your editor. It has seen so much public code that it learns common patterns, but that training also raises data ownership questions. Accuracy varies by language and task.', 'Increases developer velocity and reduces time spent on boilerplate; changes hiring bar but doesn''t eliminate junior roles.', 'Real-time token-level code prediction; integrates with LSP for context awareness.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('devin', 'Devin', '', 'Devin', ARRAY['Devin AI','Cognition Devin']::text[], 'Rising', 'An autonomous AI software engineer that can read a GitHub issue, write code, run tests, and push commits without asking.', 'A junior engineer who works alone on features end-to-end—you tell them the task, check back later, and the PR is ready.', 'You open Devin on a bug report: ''Users can''t sign up on mobile.'' Devin checks logs, finds the CSS media-query mistake, writes a test, fixes it, runs the full suite, and opens a PR.', '[]'::jsonb, 'Devin is a large multimodal model with tool use (can run terminals, browsers, text editors). It reasons through a problem step-by-step, detects when it''s stuck, backtracks, and tries again. It''s not magical—it works best on well-scoped tasks—but it''s a genuine shift in what ''AI coding'' means. Catch: still learning; occasional hallucinated commands.', 'Potential to reduce time-to-delivery on well-defined features; doesn''t replace engineers but augments their capacity.', 'Agentic architecture with tool-calling, memory, and introspection; runs in a sandboxed environment.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('autogpt', 'AutoGPT', '', 'AutoGPT', ARRAY['Auto-GPT']::text[], 'Fading', 'An early autonomous agent framework that chains together GPT calls, memory, and tool use to pursue a goal over multiple steps.', 'A to-do list that runs itself—you give it an objective, it breaks it into tasks, executes them, checks progress, and keeps going.', '''Find me the cheapest flights from NYC to Tokyo this week.'' AutoGPT spins up: searches flights, compares prices, queries hotels, summarizes the options, asks clarifying questions.', '[]'::jsonb, 'AutoGPT was viral because it showed agents before agents were productized. It''s a relatively simple loop: goal → break into subtasks → execute → reflect → loop. No sophisticated planning, just greedy step-by-step execution and memory management. It opened minds but isn''t where production agents live today.', 'Demonstrated that agents could be useful; inspired the entire agentic-coding category.', 'Loop-based design with basic memory and reflection; tokenization-heavy and prone to context drift.', 'Ecosystem, products & orgs', 30, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('babyagi', 'BabyAGI', '', 'BabyAGI', ARRAY['Baby AGI']::text[], 'Fading', 'A simplified, educational agent that creates tasks, prioritizes them, and executes them in a loop.', 'A student who writes a study plan, does the first task, sees the result, updates the plan, moves to the next—very methodical.', 'Tell BabyAGI to ''learn about machine learning.'' It creates tasks like ''Read neural network paper,'' ''Run linear regression code,'' ''Build MNIST classifier,'' and works through them.', '[]'::jsonb, 'BabyAGI is intentionally minimal—it''s a few hundred lines of Python. It loops: read task list, execute top task with GPT, get result, feed result back into task-list generation. It shows the core agent idea without real-world bells (error recovery, long-context memory). Great teaching tool; not a production framework.', 'Lowered the bar for experimenting with agentic loops; spawned the agent framework ecosystem.', 'Tiny implementation (~100 lines); uses only basic function-calling and list management.', 'Ecosystem, products & orgs', 30, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('crewai', 'CrewAI', '', 'CrewAI', ARRAY['Crew AI']::text[], 'Rising', 'A multi-agent orchestration framework where you define specialized agents, give them tools, and watch them collaborate on a task.', 'A newsroom where each reporter has a beat—one covers politics, one covers tech—and an editor coordinates the story.', 'Three agents: researcher (searches the web), writer (drafts prose), editor (fact-checks and polishes). Tell CrewAI to ''write a piece on AI regulation in 2024,'' each agent does their part, hands off to the next.', '[]'::jsonb, 'CrewAI abstracts agent design into roles, tools, memory, and handoff logic. You define each agent''s goal and tools, it manages communication between them. Behind the scenes, it''s still LLM calls and tool use, but the framework handles task routing and context passing. Feels closer to real teams than single-agent loops.', 'Enables parallel skill sets and role-based automation; speeds up complex multi-step workflows.', 'Graph-based task routing with role definitions; LLM-agnostic but optimized for Claude/GPT.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('autogen', 'AutoGen', '', 'AutoGen', ARRAY['Microsoft AutoGen']::text[], 'Rising', 'Microsoft''s framework for building multi-agent conversations where agents play roles and negotiate solutions.', 'A Slack channel where bots argue and agree their way to a solution—structured debate automation.', 'Create a ''user proxy'' agent, a ''coder'' agent, and a ''planner'' agent. They chat with each other over token limits until they converge on a plan, code, and tests.', '[]'::jsonb, 'AutoGen treats multi-agent as a conversational protocol. Agents are Python objects with state; they send messages to each other, have conversation history, and can interrupt or agree. It''s more stateful than CrewAI. Useful for back-and-forth reasoning but tokenization can explode if agents are verbose.', 'Good for workflows that need negotiation, debate, or internal validation before action.', 'Conversation-first design; built-in state management and tool registry; Python native.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('semantickernel', 'Semantic Kernel', '', 'Semantic Kernel', ARRAY['Semantic Kernel SDK','SK SDK']::text[], 'Rising', 'Microsoft''s SDK for composing prompts, models, and tools into a plug-and-play architecture for AI apps.', 'A modular synthesizer where each knob is a skill, and you wire them together to make new instruments.', 'Build a skill that translates text, chain it to a summarization skill, add tool use to fact-check sources. Swap in GPT or Claude, runs the same.', '[]'::jsonb, 'Semantic Kernel introduces ''skills'' (prompt templates + tool definitions), ''planners'' (ways to chain skills), and ''connectors'' (to models and memory stores). It''s orchestration-first: your app logic stays light, the framework handles the LLM calls. Strong on extensibility but can feel boilerplate-heavy.', 'Reduces AI engineering boilerplate; lets you define skills once and reuse across agents.', 'Plugin architecture with dependency injection; works with any LLM via adapters.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('haystack', 'Haystack', '', 'Haystack', ARRAY['DeepSet Haystack']::text[], 'Rising', 'An open-source framework for building retrieval-augmented applications with a drag-and-drop pipeline metaphor.', 'A flow chart for your RAG app—drop in document retrievers, rerankers, and generators, wire them up.', 'Build a customer-support chatbot: document loader → splitter → embedding model → retriever → prompt template → LLM generator. Test the whole pipeline with sample data.', '[]'::jsonb, 'Haystack started as a RAG tool but has evolved into a general orchestration layer. You define components (Node), wire them (Pipeline), test them. Strong for RAG, weaker than Semantic Kernel for general agent orchestration. Active community; good documentation.', 'Shortens time-to-RAG deployment; supports experimenting with different chunking and retrieval strategies.', 'Graph-based pipeline design; strong typing and testability.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('mlflow', 'MLflow', '', 'MLflow', ARRAY['MLflow tracking']::text[], 'Core', 'An open-source platform for managing the ML lifecycle—from experiments to production deployment.', 'Git for machine learning: track every model version, roll back, compare metrics.', 'Log a training run with MLflow, it records code, params, metrics, and the model artifact. Later, register it, promote it to staging, deploy to prod. Full audit trail.', '[]'::jsonb, 'MLflow has four components: Tracking (logs runs), Projects (reproducible execution), Models (unified format), Registry (deployment workflow). It''s agnostic to the framework and runs on your infrastructure or their cloud. Widely adopted in enterprises; plays well with Databricks.', 'Critical for model governance and compliance; enables safe promotion of models through stages.', 'Run-level granularity; model registry with versioning and transitions.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('langsmith', 'LangSmith', '', 'LangSmith', ARRAY['LangSmith platform','LangChain observability']::text[], 'Core', 'LangChain''s observability and debugging platform for tracing LLM calls, evaluating outputs, and catching issues in production.', 'A debugger for your LLM app—set breakpoints on prompts, inspect tool outputs, replay failures.', 'Your RAG app makes a weird answer. In LangSmith, you see the exact retrieval results, the prompt that was sent, the model response, and the tool calls—drill down to diagnose the bug.', '[]'::jsonb, 'LangSmith logs every LLM call and tool invocation in a trace tree. You can tag runs, write evals (pass/fail checks), and compare eval scores across commits. It integrates with LangChain but works with any app via their SDK. Strong for catching regressions before production.', 'Reduces debugging time on production LLM issues; enables metric-driven improvements.', 'Trace-based debugging; custom evaluation logic; replay and diff of runs.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('langgraph', 'LangGraph', '', 'LangGraph', ARRAY['LangGraph framework']::text[], 'Rising', 'LangChain''s graph-based orchestration layer for defining multi-step agents and workflows as state machines.', 'A flowchart for your agent: define states, edges (transitions), and handlers (what runs at each state).', 'An agent has states: thinking, planning, executing, reflecting. Transitions depend on whether the agent thinks it''s done. LangGraph manages the loop and state passing.', '[]'::jsonb, 'LangGraph is a thin layer over agentic loops that makes the structure explicit—state is first-class, edges are conditions, handlers are functions. It forces you to think about state shape upfront, which reduces bugs. Persists state, so you can resume interrupted tasks or replay for debugging.', 'Makes agent behavior predictable and testable; enables state-based recovery.', 'Graph-based DAG execution; state persistence; deterministic replay.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('dspy', 'DSPy', '', 'DSPy', ARRAY['Stanford DSPy']::text[], 'Rising', 'A framework from Stanford that treats prompts as compilers—optimize them automatically using training data and evaluations.', 'Instead of hand-writing prompts, write a program and let DSPy optimize the prompts inside it.', 'Define a module: input text → summarizer → translator → QA. You write the high-level flow, DSPy learns the best prompts for each step from examples and validates on a test set.', '[]'::jsonb, 'DSPy decouples logic from prompts. You write Python functions that call LLMs via DSPy primitives; DSPy optimizes the prompts under the hood by looking at training data and your evaluations. This shifts prompting from art to engineering. Young but growing in adoption; changes mindset from ''what prompt works'' to ''what examples and structure work.''', 'Reduces manual prompt tuning; brings structure and measurability to prompt engineering.', 'Compiler-based prompt optimization; training-free adaptation; evaluations drive improvement.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('guidance', 'Guidance', '', 'Guidance', ARRAY['Guidance language']::text[], 'Rising', 'A domain-specific language for writing prompts with embedded control flow—branches, loops, and structured output.', 'A templating language that''s smart about token usage and can bail out early if the model is going off the rails.', 'Write a template: ''Generate 3 tweets: {{for i in range(3)}} Tweet {{i+1}}: {{generate max_tokens=20 stop=''\n''}} {{/for}}'' Guidance renders it, streams output, stops early if needed.', '[]'::jsonb, 'Guidance compiles prompts with control logic into a guided generation plan. The model streams tokens, Guidance constrains which tokens are valid at each step (e.g., next must be JSON). Saves tokens because you''re not generating garbage. Integrates with vLLM and Hugging Face transformers.', 'Reduces token waste and cost on structured generation; improves reliability of JSON/code output.', 'Token-level guidance; integrates with vLLM for efficiency; open-source.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('instructor', 'Instructor', '', 'Instructor', ARRAY['Instructor library','structured outputs']::text[], 'Rising', 'A Python library that wraps LLM APIs and guarantees structured outputs (JSON, dataclasses, Pydantic models) by validating and retrying.', 'A typesafe layer on top of LLM completion—ask for an object, get an object or an error.', 'Define a Pydantic model for a customer record. Call instructor.create(model=Customer, prompt=''Extract customer from this email''). Get a fully-validated Customer object or a retry loop.', '[]'::jsonb, 'Instructor patches OpenAI/Anthropic SDKs to add a `response_model` parameter. It uses the schema to prompt the model, validates the output, and retries if validation fails. You don''t write parsing logic; you just define the schema. Massively reduces boilerplate for structured extraction.', 'Turns schema validation into a no-brainer for structured tasks; cuts downstream data bugs.', 'Pydantic-native; patches LLM SDKs; automatic retry with backoff.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('pydanticai', 'Pydantic AI', '', 'Pydantic AI', ARRAY['Pydantic AI framework']::text[], 'Rising', 'Pydantic''s agent framework that uses type hints to define agents, structure prompts, and validate tool outputs.', 'A strongly-typed agent framework—define your agent''s tools and outputs as Python types, Pydantic enforces them.', 'Write an agent method with return type `QueryResult`. Define what QueryResult looks like. The framework ensures the model response matches; if not, retry.', '[]'::jsonb, 'Pydantic AI is a new entrant that treats types-first. You define agent behaviors as classes with typed methods. Tool definitions are auto-generated from type hints. Works with any LLM. Smaller than LangChain but opinionated. Still early but gaining traction in Pydantic ecosystem.', 'Type safety reduces production errors; enables IDE autocomplete for agent definitions.', 'Type-first design; auto-generated tool schemas; composable agent classes.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('opensourceai', 'open source AI', '', 'open source AI', ARRAY['open-source models','OSS models']::text[], 'Core', 'Models released with weights publicly available, usually under permissive licenses, enabling anyone to run, modify, or redistribute them.', 'The difference between owning a car and renting one—open-source models are yours to tinker with.', 'Llama, Mistral, Gemma, OLMo. Download them, fine-tune them on your data, deploy on your hardware, modify the architecture.', '[]'::jsonb, 'Open-source AI is a spectrum—some models are research releases, others are production-ready. They come with training data, architecture details, and sometimes training code. Tradeoff: full control and transparency, but you own the compute to run and update them. Closed models are often better, but OS models are catching up.', 'Reduces lock-in and enables custom fine-tuning; shifts cost from API to infrastructure.', 'Full stack control; can optimize for latency, privacy, cost.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('modellicensing', 'model licensing', '', 'model licensing', ARRAY['model license']::text[], 'Core', 'The legal terms under which a model can be used—commercial, non-commercial, research-only, personal-use, etc.', 'A software license but for the model weights themselves—defines who can do what with them.', 'Llama 2 is open-source but restricted: not for competing with Meta. Mistral is fully open. GPT is proprietary (license only to use via API).', '[]'::jsonb, 'Model licensing is a minefield. Some licenses restrict commercial use, some restrict creating competing models, some are vague about derived works. There''s no standard. You need to check before deploying: can you use it for your use case, can you fine-tune, can you sell services built on it?', 'Critical for legal compliance; affects which models you can use and how.', 'Determines whether you can self-host, fine-tune, or redistribute.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('apache20', 'Apache 2.0', '', 'Apache 2.0', ARRAY['Apache License 2.0']::text[], 'Core', 'A permissive open-source software license that lets you use, modify, and redistribute code freely, with just attribution and a notice of changes.', 'It''s like Creative Commons for code—share-alike, but you must credit the original.', 'Llama, PyCUDA, and many ML tools use Apache 2.0. You can modify Llama, sell a service on top, and you just have to include a copy of the license.', '[]'::jsonb, 'Apache 2.0 explicitly grants patent rights, so if the licensor sues you over patents, the license terminates. It''s one of the most permissive licenses; compared to GPL, it doesn''t force your code to be open. Clear, battle-tested, widely recognized.', 'Enables commercial use without reciprocal obligations; lowers friction for adoption.', 'Patent grant included; no copyleft requirement.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('mitlicense', 'MIT license', '', 'MIT license', ARRAY['MIT License']::text[], 'Core', 'The simplest open-source license—do whatever you want with the code, just keep the copyright notice.', 'Public domain but with a tiny string attached: you have to mention who wrote it.', 'Django, React, Rails. You can use them, modify them, sell products on top, all you need is a copy of the MIT license and original author name.', '[]'::jsonb, 'MIT is shorter than Apache 2.0 and doesn''t have explicit patent language, but it''s so permissive that patents are largely irrelevant (you''re getting the code, not the idea). Very popular for open-source; sometimes too lenient if you want reciprocal openness.', 'Frictionless adoption; maximum permissiveness.', 'Shortest license text; no patent grant but no restrictions.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('inferenceprovider', 'inference provider', '', 'inference provider', ARRAY['model provider','LLM provider']::text[], 'Core', 'A company or service that runs LLM inference at scale and sells API access by the token.', 'A gas station for language models—you pay per gallon, they handle the pumps.', 'Anthropic (Claude API), OpenAI (ChatGPT API), Together, Mistral, Groq. You send text, they compute the response, bill you.', '[]'::jsonb, 'Inference providers differ by model choice (which models do they offer), latency, pricing per token, rate limits, and feature support (streaming, function-calling, long context). Some (Anthropic, OpenAI) are vertically integrated; others (Together, Replicate) are aggregators or infrastructure plays.', 'Shifts capex (buying GPUs) to opex (API spend); enables rapid experimentation.', 'Abstracts away hardware; you focus on prompt and usage patterns.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('aiwrapper', 'AI wrapper', '', 'AI wrapper', ARRAY['wrapper startup']::text[], 'Rising', 'A startup or product that wraps an LLM API with a nicer UX, domain-specific features, or integrations, but doesn''t train its own model.', 'A restaurant that orders ingredients from a supplier and adds skill, plating, and atmosphere.', 'Jasper wraps GPT to write marketing copy. Typeform wraps GPT to auto-suggest form questions. They''re not training models; they''re tuning prompts and building UI.', '[]'::jsonb, 'Wrapper companies have lower moats than model builders—if they can be out-competed by better models or better integrations, they can disappear. But they own relationships and workflows. Debate: is a wrapper valuable? Some say yes (brand, UX, integration), others say it''s a race to zero.', 'Low barrier to entry but high customer acquisition cost; margins erode if the underlying model improves.', 'Thin application layer; heavy dependence on upstream model''s quality and stability.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('moat', 'moat', '', 'moat', ARRAY['competitive moat','economic moat']::text[], 'Core', 'A defensible advantage—something that makes a business hard to copy or beat, even if a competitor has better tech.', 'A castle''s moat keeps invaders out; a company''s moat keeps competitors out.', 'Network effects (everyone uses it), switching costs (too expensive to leave), scale advantages (cheapest at size), brand (people trust it). In AI: data, compute, the model itself, distribution.', '[]'::jsonb, 'In AI, moats are hotly debated. Does a big model have a moat? Maybe not—competition is fierce. Does a fine-tuned model on proprietary data have a moat? Possibly. Does distribution (integrations, brand, network) have a moat? Often yes. The most enduring moats are usually not the tech.', 'Moat determines long-term defensibility; shapes pricing power and profitability.', 'Data, scale, and network effects are the strongest technical moats.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('apiplatform', 'API platform', '', 'API platform', ARRAY['API service']::text[], 'Core', 'A service that exposes models or tools via HTTP endpoints, handling auth, rate-limiting, versioning, and billing.', 'A library with a librarian at the desk—you ask for what you want, they fetch it, you pay.', 'OpenAI API, Anthropic API, Replicate. You send HTTP requests, get responses, pay based on usage.', '[]'::jsonb, 'API platforms abstract infrastructure. They handle load balancing, uptime, security, and billing. They''re how most production LLM applications consume models. The model itself is commodity; the platform (reliability, features like streaming, caching, batch processing) is differentiator.', 'Reduces capital and operational burden; enables pay-as-you-go scaling.', 'RESTful or gRPC; stateless; rate-limited; async options.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('playground', 'playground', '', 'playground', ARRAY['model playground','interactive UI']::text[], 'Core', 'A web interface where you can type a prompt, adjust settings like temperature or top-p, and see model responses in real time without writing code.', 'A test kitchen—try recipes before you cook for guests.', 'ChatGPT, Claude.ai, Mistral''s web interface. Type a prompt, tweak the slider for creativity (temperature), hit send, see output.', '[]'::jsonb, 'Playgrounds lower the barrier to experimentation. No API keys, no code, instant feedback. Often they have features APIs don''t (image upload, voice, multimodal). Downside: you''re not version-controlling your prompts, and playgrounds don''t scale to production load.', 'Onboarding tool; lets non-technical people experiment and build intuition.', 'Useful for prompt iteration before productionizing via API.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('finetuningapi', 'fine-tuning API', '', 'fine-tuning API', ARRAY['fine-tune API']::text[], 'Core', 'An API endpoint where you upload training data and request the model to fine-tune on it, returning a new model variant optimized for your task.', 'Sending your generic car to a shop and saying ''make it handle better on mountain roads''—you get a custom variant back.', 'Upload 500 examples of customer emails + correct support-ticket categories. Call the fine-tuning API. In an hour, get back a model that''s better at categorization than the base model.', '[]'::jsonb, 'Fine-tuning APIs run the training loop on their hardware, charge by token or example, and give you a model checkpoint to call. Tradeoff: you don''t see training loss curves, you can''t customize loss functions, but you''re not managing GPUs. Popular for task-specific optimization when in-context examples don''t cut it.', 'Improves model quality on domain tasks; more cost-effective than prompt engineering beyond a certain threshold.', 'Managed training; no GPU setup; token-based pricing.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('assistantsapi', 'assistants API', '', 'assistants API', ARRAY['assistants endpoint','assistant']::text[], 'Core', 'An API for creating persistent assistants that remember conversation history, manage state, and have built-in tool support.', 'Like ChatGPT but for your application—conversation continuity, file upload, tool calls, all via API.', 'Create an assistant that''s a tax advisor. Upload tax documents via API, start a thread (conversation), send messages. The assistant remembers context and has access to a calculator tool.', '[]'::jsonb, 'The assistants API abstracts conversation state management. You create an assistant once, start threads with users, send messages, and the API handles token limit management and tool invocation. Works well for chatbot-like applications but can be less flexible than raw chat API.', 'Simplifies conversational AI deployment; built-in memory and state.', 'Thread-based conversation management; file handling; built-in tool registry.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('batchapi', 'batch API', '', 'batch API', ARRAY['async batching']::text[], 'Core', 'An API endpoint where you upload a file of requests, pay a discount for processing in batch (not real-time), and get results back when they''re ready.', 'Bulk mail—drop off 1000 letters at the post office, get a discount, pick them up tomorrow.', 'You have 10,000 customer reviews to classify. Upload a JSON lines file to the batch API at 50% cost, queue it, retrieve results in an hour.', '[]'::jsonb, 'Batch APIs trade latency for cost. You don''t get results immediately, but you pay 50% less per token. Good for non-urgent work (nightly processing, backfill, evaluation runs). Implementation: upload JSONL → get batch ID → poll status → download results.', 'Cuts costs for large-scale offline inference; enables affordable batch analytics.', 'Async processing; bulk JSONL uploads; usually 50% discount.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('embeddingsapi', 'embeddings API', '', 'embeddings API', ARRAY['embedding endpoint']::text[], 'Core', 'An API that converts text into a vector (embedding), useful for similarity search, clustering, and semantic retrieval.', 'A fingerprint—instead of storing the whole face, store a short code that captures its essence.', 'Call the API with ''The cat sat on the mat'' and get back a 1536-dim vector. Call it again with ''A feline rested on fabric.'' Vectors are similar; high cosine similarity means semantic match.', '[]'::jsonb, 'Embeddings come from the model''s internal representations. Different models have different dimension sizes (OpenAI 1536, newer ones smaller). Embeddings are how you enable semantic search (RAG''s backbone). Once you have embeddings, store them in a vector DB, search by distance.', 'Core for RAG; enables semantic search without ever running a full LLM.', 'Fast (usually <100ms), small output, critical for retrieval pipelines.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('visionapi', 'vision API', '', 'vision API', ARRAY['image API','multimodal API']::text[], 'Core', 'An API endpoint that takes an image and returns an analysis—caption, object detection, OCR, reasoning about visual content.', 'Giving a description of a painting to a blind person; the model translates pixels to words.', 'Send a photo of a receipt to Claude''s vision API. Get back line items, total, vendor, date—all extracted and structured.', '[]'::jsonb, 'Vision APIs work because large models are trained on both images and text. They can answer ''what''s in this image,'' ''describe the text,'' ''count the objects,'' etc. Multimodal models like GPT-4V and Claude 3 handle this natively. Vision adds a dimension to automation (no more manual data entry from PDFs).', 'Enables automation of visual tasks (invoice processing, content moderation); unblocks new user workflows.', 'Takes images as base64 or URLs; streaming not yet common; usually slower than text.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('realtimeapi', 'realtime API', '', 'realtime API', ARRAY['real-time API','streaming audio','voice API']::text[], 'Rising', 'An API that ingests audio streams, transcribes, runs LLM reasoning, and outputs audio responses—low latency, no round trips.', 'A phone call instead of email—talk and get an immediate response, with reasoning happening behind the scenes.', 'User speaks: ''What''s the weather in NYC?'' Realtime API transcribes (speech-to-text), asks the LLM (which checks a weather tool), and speaks the response back—whole loop <500ms.', '[]'::jsonb, 'Realtime APIs use WebSocket or similar for true streaming. They interleave transcription, LLM inference, and TTS. Requires high reliability and low-latency infrastructure. Relatively new; OpenAI, Anthropic, and others are rolling these out. Game-changer for voice agents.', 'Enables voice-first experiences; reduces friction for hands-free interaction.', 'WebSocket/streaming architecture; complex latency management; requires efficient inference.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('functioncallingapi', 'function calling API', '', 'function calling API', ARRAY['tool use API']::text[], 'Core', 'An API feature that lets you define functions (tools), and the model decides when and how to call them with structured arguments.', 'Giving the model a menu of abilities—it looks at the request and picks which ability to use.', 'Define functions: ''get_weather(city)'' and ''search_flights(from, to, date)''. User asks ''flights to LA next week.'' Model returns JSON: {function: ''search_flights'', args: {from: ''NYC'', to: ''LA'', date: ...}}.', '[]'::jsonb, 'Function calling is how agents work at scale. Instead of prompting the model to generate command text, it returns structured JSON that names the function and arguments. Reduced hallucination, easier parsing, composable. All major APIs now support it.', 'Enables reliable agent workflows; reduces parsing errors and cost from retries.', 'Structured output; LLM returns function name and JSON args, not free text.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('gpts', 'GPTs', '', 'GPTs', ARRAY['GPTs (OpenAI)','custom GPT']::text[], 'Core', 'OpenAI''s way of packaging a prompt, instructions, knowledge files, and tool integrations into a shareable chatbot, without code.', 'A template for ChatGPT—set the personality, upload docs, link to your tools, share a link.', 'Create a GPT called ''Tax Advisor'' with IRS docs and a calculator tool. Share a link; anyone can chat with it. No coding required.', '[]'::jsonb, 'GPTs are ChatGPT + configuration + files + tools. Under the hood, they''re still just LLM calls, but the packaging makes them accessible to non-engineers. You can publish them, sell them, or keep them private. Limited: no custom training, no fine-tuning, constrained to OpenAI''s ecosystem.', 'Democratizes agent deployment; enables non-technical users to build AI assistants.', 'Configuration-based; no code; limited to ChatGPT capabilities.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('custominstructions', 'custom instructions', '', 'custom instructions', ARRAY['custom system prompt']::text[], 'Core', 'A feature where you set persistent instructions (like ''always be concise'' or ''i''m in the UK'') that apply to all chats with a model.', 'A standing order with a waiter—every time you visit, they remember your preferences.', 'Add instruction: ''I''m a software engineer; assume technical knowledge.'' Now every chat with ChatGPT starts with that context.', '[]'::jsonb, 'Custom instructions are stored client-side and prepended to the system message. They''re convenient for personalization but don''t update the model weights—just the prompt. Downside: they take up context window tokens.', 'Improves UX personalization; reduces need to repeat context.', 'Client-side prompt modification; simplest form of personalization.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('systemcard', 'system card', '', 'system card', ARRAY['system card report','responsible release']::text[], 'Rising', 'Documentation that describes a model''s capabilities, limitations, testing methodology, and known failure modes.', 'A nutritional label on a food product—ingredients, allergens, serving size.', 'A system card might say: ''Claude 3 Opus: tested on MMLU with 88.7% accuracy, struggles with obscure foreign languages, refusal rate 2%.''', '[]'::jsonb, 'System cards come from responsible AI practices. They''re meant to inform users about what to expect and what to watch for. No standard format; varies by lab. Good ones include: capability claims with citations, limitations (what doesn''t work), evaluation results, known harm categories.', 'Reduces risk of misuse; sets user expectations; helps compliance teams assess safety.', 'Transparency tool; should include eval results and limitations.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('modelspec', 'model spec', '', 'model spec', ARRAY['model specification']::text[], 'Rising', 'A technical document describing the model''s architecture, training data, training methodology, and design choices.', 'The blueprint for a car—engine specs, fuel type, suspension tuning.', 'GPT-4 model spec (partially public): uses a Transformer architecture, trained on diverse internet data through Dec 2023, uses RLHF for alignment.', '[]'::jsonb, 'Model specs are deeper than system cards. They''re written for engineers and researchers. They include training objectives, architecture details, scaling laws used, hardware requirements, and reproducibility notes. Full transparency is rare (competitive concerns), but increasing pressure for openness.', 'Informs deployment decisions: latency, cost, capabilities.', 'Critical for reproducibility and fine-tuning decisions.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('responsiblescalingpolicy', 'responsible scaling policy', '', 'responsible scaling policy', ARRAY['scaling policy','RSP']::text[], 'Rising', 'A lab''s published commitment to pause or test larger models if certain safety risks emerge during training.', 'An alarm system that trips if the house gets too hot—you''ve committed to checking before it burns down.', 'Anthropic''s RSP: ''If we detect certain red-line capabilities during training, we''ll pause, do further testing, and only proceed if we can mitigate risks.''', '[]'::jsonb, 'RSPs are a credible commitment device—a lab announces in advance that it will slow down if specific risk thresholds are crossed. Hard to enforce (who checks?), but signals seriousness about safety. Different labs have different thresholds and procedures.', 'Signals safety commitment to regulators and public; reduces reputational risk.', 'Gating on evals; capability measurements tied to go/no-go decisions.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('frontiersafety', 'frontier safety', '', 'frontier safety', ARRAY['frontier AI safety','advanced AI safety']::text[], 'Rising', 'Research and practices aimed at ensuring very large, capable models don''t cause harm—evaluating risks, designing mitigations, and testing before deployment.', 'Pilot testing a new plane design in a simulator before flying with passengers.', 'Before releasing Claude 3, Anthropic evaluated it on biosecurity, autonomous hacking, and planning capabilities—measuring failure modes, then building guardrails.', '[]'::jsonb, 'Frontier safety is high-stakes because the risks are abstract and potentially existential. It''s not traditional cybersecurity; it''s about what a superhuman model might be capable of and how to prevent misuse. Evals, interpretability, RLHF, capability monitoring all fall under it.', 'Risk management for advanced models; required by regulators in some regions.', 'Red-teaming, adversarial testing, evals on dangerous capabilities.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('aiagentplatform', 'AI agent platform', '', 'AI agent platform', ARRAY['agent platform']::text[], 'Rising', 'A managed service or framework for building, deploying, and running autonomous agents—handles orchestration, memory, tools, and monitoring.', 'A PaaS for agents—you define the agent, the platform runs it at scale.', 'Anthropic''s Agents API (coming), cloud platforms like Replit Agent. Upload your agent logic, plug in tools, invoke it; platform handles load, scaling, observability.', '[]'::jsonb, 'Agent platforms abstract away infrastructure and state management. They handle long-running tasks, retries, parallel tool calls, and cost tracking. Emerging category; lines blur with frameworks (LangGraph, CrewAI, AutoGen) and LLM providers (Anthropic, OpenAI).', 'Reduces time-to-deployment for agentic features; enables scaling without ops overhead.', 'Managed infrastructure; agent persistence; built-in monitoring.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('foundationmodelprovider', 'foundation model provider', '', 'foundation model provider', ARRAY['model lab']::text[], 'Core', 'A company that trains and releases large foundation models (GPT, Claude, Llama) for others to build on.', 'A quarry that extracts and sells raw stone; others carve it into sculptures.', 'Anthropic, OpenAI, Meta, Google. They invest billions in compute, training data, and research to release models.', '[]'::jsonb, 'Foundation model providers are capital-intensive. They own distribution (API or weights), training data, and infrastructure. High barrier to entry but huge leverage if you get it right. Increasingly saturated (30+ labs releasing competitive models).', 'Controls pricing and model quality; gatekeeps capabilities.', 'Massive R&D required; scaling laws and architecture drive differentiation.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('hyperscaler', 'hyperscaler', '', 'hyperscaler', ARRAY['cloud hyperscaler','megacloud']::text[], 'Core', 'A massive cloud provider (AWS, GCP, Azure) that operates at planetary scale with millions of GPUs and data centers worldwide.', 'The electricity grid—pervasive, invisible, enables everything else.', 'AWS, Microsoft Azure, Google Cloud. They have more compute than most nations. AI providers train models on their infra.', '[]'::jsonb, 'Hyperscalers are becoming AI players in their own right. Azure/OpenAI partnership, Google''s Gemini, AWS''s Bedrock. They own customer relationships, billing, and compliance. For AI labs, training at hyperscaler scale is necessary; for users, hyperscalers offer consolidated services.', 'Hyperscaler backing means compute availability and compliance support; adds moat.', 'Massive parallel infrastructure; optimized for LLM training and serving.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('aichip', 'AI chip', '', 'AI chip', ARRAY['AI accelerator']::text[], 'Core', 'A specialized processor (GPU, TPU, NPU) optimized for training and inferencing neural networks—faster and cheaper than CPUs for AI.', 'A engine built specifically for speed; a car engine, not a truck engine.', 'NVIDIA''s H100, Google''s TPU, Apple''s Neural Engine. Each optimized for matrix operations that power neural nets.', '[]'::jsonb, 'AI chips are the bottleneck. Demand >> supply. NVIDIA dominates (80%+ market share). Alternatives exist (TPU, Cerebras, Graphcore) but are niche or closed. Everyone wants to design their own chip for cost/advantage; success is rare.', 'Chip availability and cost directly limit model size and deployment scale.', 'Matrix-optimized; high bandwidth memory; interconnect is critical for distributed training.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('tpupod', 'TPU pod', '', 'TPU pod', ARRAY['tensor processing unit cluster']::text[], 'Core', 'Google''s tensor processing unit arranged in a cluster—thousands of TPUs connected for training billion-parameter models.', 'A skyscraper of specialized processors—each floor is a TPU, elevator is the interconnect.', 'A TPU v4 pod has 4,096 TPUs. Google trains PaLM and Gemini on TPU pods. Extremely expensive, extremely fast for matrix ops.', '[]'::jsonb, 'TPU pods are specialized for tensor operations but less flexible than GPUs (harder to program). Google uses them for its own models but doesn''t sell pods directly to researchers. Access via Colab free tier (limited), GCP (expensive), or research grants.', 'Differentiates Google''s capabilities; high moat because it''s proprietary.', 'Optimized for dense matrix ops; custom Google software stack.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('gpucloud', 'GPU cloud', '', 'GPU cloud', ARRAY['GPU rental','compute cloud']::text[], 'Core', 'A service that rents GPUs by the hour—useful for training models without buying hardware.', 'Renting a bulldozer instead of owning one—pay per day, return when done.', 'Lambda, CoreWeave, RunPod, Modal. Rent H100s at $3-5/hour, SSH in, train your model.', '[]'::jsonb, 'GPU clouds democratized model training. No upfront $500k investment; pay as you go. Tradeoff: you pay a premium (more than data center rental), and availability fluctuates. Newer providers are targeting AI workloads specifically.', 'Lowers barrier to entry for training; shifts capex to opex.', 'Hourly billing; SSH/cloud APIs; community-built; less reliable than owned infra.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('tokenpricing', 'token pricing', '', 'token pricing', ARRAY['pricing model']::text[], 'Core', 'The cost model where LLM APIs charge per token consumed (input and output), not per request or per hour.', 'Cell phone billing—pay for minutes (tokens) used, not a fixed monthly fee.', 'Claude API: $3 per 1M input tokens, $15 per 1M output tokens. A 1,000-token response costs $0.015.', '[]'::jsonb, 'Token pricing aligns incentives—longer responses cost more, so you think about efficiency. But it''s opaque (users don''t know how many tokens their text will tokenize to). Output tokens usually cost more than input (generation is harder). Pricing pressure from competition.', 'Transparent and usage-based; scales naturally with demand.', 'Tokenization adds latency; cache/batch pricing is becoming differentiator.', 'Ecosystem, products & orgs', 80, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('promptcachingapi', 'prompt caching API', '', 'prompt caching API', ARRAY['cache API']::text[], 'Rising', 'An API feature where you cache the prefilled tokens (prompt, system instructions, uploaded documents) and pay less to reuse them in follow-up queries.', 'Prepping ingredients the night before—do the expensive work once, reuse for multiple meals.', 'Upload a 100k-token document. Tell the API to cache it. Make 10 queries against the doc. You pay full price for the first query, discount (e.g., 10%) for the rest.', '[]'::jsonb, 'Prompt caching reuses KV cache entries from initial processing. It requires exact match of prefix tokens (so changing system prompt breaks cache). Saves both cost and latency. Relatively new feature; adoption growing.', 'Reduces cost for document-heavy workflows; enables conversation-over-documents at scale.', 'KV cache management; prefix matching; usually 90% discount on cached tokens.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[]),
  ('structuredoutputsapi', 'structured outputs API', '', 'structured outputs API', ARRAY['structured generation']::text[], 'Rising', 'An API feature that constrains model output to match a user-defined JSON schema, guaranteeing valid structure without retries.', 'A form with checkboxes and text fields instead of a blank piece of paper—shape the output before the model writes.', 'Define a schema for a customer record: {name: string, age: number, email: string}. Model must return valid JSON matching that schema.', '[]'::jsonb, 'Structured outputs work by constraining token generation—only allowing tokens that lead to valid JSON. Faster than retry loops, no wasted tokens on malformed output. Recent addition to APIs; changes how you think about extraction tasks.', 'Eliminates downstream JSON parsing errors; speeds up structured extraction.', 'Token-level constraint; ensures schema compliance; integrated with function-calling.', 'Ecosystem, products & orgs', 60, ARRAY['seed','ecosystem-products-orgs']::text[])
